/**
 * One claim with its evidence (D40): the claim, the result line, and the full note on tap. [text] is the claim when
 * note.showsClaim, else the fact's label (the row then says „nicht belegt“). Whole row ≥ 56 dp.
 */
@Composable
fun SbClaimRow(
    text: String,
    note: SbNote,
    onHowChecked: () -> Unit,
    modifier: Modifier = Modifier,
